      dependencies.push(dependency);
    });

    tasks.push({ id: rawTask.id, duration: rawTask.duration, dependsOn: dependencies });
  });

  for (const [index, task] of tasks.entries()) {
    for (const dependency of task.dependsOn) {
      if (dependency === task.id) {
        throw new InputError(`tasks[${index}] cannot depend on itself: ${JSON.stringify(task.id)}`);
      }
      if (!ids.has(dependency)) {
        throw new InputError(
          `tasks[${index}].dependsOn references unknown task: ${JSON.stringify(dependency)}`,
        );
      }
    }
  }

