  const nodes = cycle.slice(0, -1);
  let best = nodes;

  for (let offset = 1; offset < nodes.length; offset += 1) {
    const rotated = nodes.slice(offset).concat(nodes.slice(0, offset));
    if (comparePaths(rotated, best) < 0) best = rotated;
  }

