      start = Math.max(start, earliest[dependency].finish);
      bestPreviousWeight = Math.max(bestPreviousWeight, criticalWeight.get(dependency)!);
    }

    layerById.set(id, layer);
    (layers[layer] ??= []).push(id);
    earliest[id] = { start, finish: start + task.duration };

    const candidatePaths: string[][] = [[id]];
    for (const dependency of task.dependsOn) {
      if (criticalWeight.get(dependency) === bestPreviousWeight) {
        candidatePaths.push(bestPath.get(dependency)!.concat(id));
      }
